<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNIFCO | بوابة العميل</title><style>:root{font-family:Tahoma,Arial,sans-serif;--navy:#1e315b;--dark:#132137;--red:#ce122d;--light:#f7f9fc;--muted:#68758a}*{box-sizing:border-box}body{margin:0;background:var(--light);color:var(--dark)}.top{background:#fff;border-bottom:1px solid #e5eaf1;position:sticky;top:0;z-index:10}.wrap{width:min(1320px,94%);margin:auto}.nav{display:flex;align-items:center;gap:18px;min-height:74px}.logo{width:110px;height:58px;object-fit:contain;margin-left:auto}.btn{border:0;background:var(--navy);color:#fff;padding:9px 13px;border-radius:8px;font-weight:700;text-decoration:none;cursor:pointer}.btn.red{background:var(--red)}.btn.light{background:#eef3fa;color:var(--navy)}.hero{padding:26px 0}.hero h1,h2{color:var(--navy)}.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:18px;box-shadow:0 3px 12px rgba(19,33,55,.04)}.metric{font-size:28px;font-weight:800;color:var(--navy)}.section{margin:20px 0}.tabs,.filters{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.tabs a{padding:8px 10px;background:#fff;border:1px solid #dfe5ee;border-radius:8px;color:var(--navy);text-decoration:none;font-weight:700;font-size:13px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border-bottom:1px solid #edf0f5;text-align:right;vertical-align:top;font-size:13px}th{background:#f5f7fa;color:var(--navy)}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef3fa}.high{background:#fff1f2;color:#b42339}.ok{background:#eaf8ef;color:#207a43}.table-wrap{overflow-x:auto;border:1px solid #e4e9f0;border-radius:12px;background:#fff}.asset-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.asset{background:#fff;border:1px solid #e3e8ef;border-radius:12px;padding:16px